#include <utility>
#include <iostream>

int main() {
    std::pair<int, int> p1(10, 20);
    std::pair<int, int> p2(10, 30);
    std::pair<int, int> p3(5, 50);

    // Comparison prioritizes first element
    std::cout << (p3 < p1) << "\n"; // 1 (5 < 10)

    // If first elements are equal, second element decides
    std::cout << (p1 < p2) << "\n"; // 1 (10 == 10, but 20 < 30)

    // If both are equal
    std::cout << (p1 < p1) << "\n"; // 0 (false)
}
